def icon(kind, size=20):
    paths = {'video':'<rect x="3" y="5" width="13" height="14" rx="3"/><path d="m16 10 5-3v10l-5-3"/>', 'image':'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m4 17 5-5 4 4 3-3 5 5"/>', 'person':'<circle cx="12" cy="7" r="3"/><path d="M6 21v-3a6 6 0 0 1 12 0v3"/>', 'box':'<path d="m12 3 9 5v9l-9 5-9-5V8zM3 8l9 5 9-5M12 13v9M8 5l9 5"/>', 'clock':'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 3"/>', 'sound':'<path d="M3 9h4l5-5v16l-5-5H3zM16 8a7 7 0 0 1 0 8M19 5a11 11 0 0 1 0 14"/>', 'settings':'<path d="M3 7h18M3 17h18"/><circle cx="9" cy="7" r="3" fill="white"/><circle cx="15" cy="17" r="3" fill="white"/>', 'model':'<path d="M4 17V9M9 20V4M14 16V8M19 19V6"/>', 'spark':'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>'}
    return f'<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round">{paths.get(kind,paths["image"])}</svg>'

def art(kind='product'):
    if kind=='person':
        return '<svg viewBox="0 0 70 90"><rect x="0" y="0" width="70" height="90" fill="#e8e9e7"/><ellipse cx="35" cy="34" rx="12" ry="15" fill="#bdc9c0"/><path d="M12 88V69c0-17 46-17 46 0v19" fill="#93aba0"/><path d="M23 32c-3-23 32-23 25 4l-9-13z" fill="#697f72"/></svg>'
    if kind=='video':
        return '<svg viewBox="0 0 70 90"><rect width="70" height="90" fill="#eae7db"/><path d="M0 62h70v28H0z" fill="#c9cbbb"/><path d="M9 25h24v33H9z" fill="#f5f4eb"/><path d="M42 17h15v45H42z" fill="#cfdbc5"/><path d="m10 80 9-28h28l12 28" fill="#afa991"/><rect x="27" y="47" width="15" height="26" rx="3" fill="#5c8a74"/><rect x="30" y="40" width="9" height="8" rx="2" fill="#4d6655"/></svg>'
    return '<svg viewBox="0 0 70 90"><ellipse cx="35" cy="78" rx="21" ry="4" fill="#d2decf"/><rect x="22" y="23" width="27" height="53" rx="6" fill="#6c9c81"/><rect x="27" y="11" width="17" height="15" rx="3" fill="#375a47"/><rect x="26" y="42" width="19" height="20" rx="1" fill="#ebeadb"/><path d="M29 48h13M29 53h9M29 57h11" stroke="#93a28a"/></svg>'

def add(label,kind,disabled=False,sub='',new=False):
    return f'<button class="add {"new" if new and not disabled else ""}" {"disabled" if disabled else ""}>{"<span class=new-label>新增</span>" if new and not disabled else ""}{icon(kind)}<span>{label}</span>{f"<span class=under>{sub}</span>" if sub else ""}</button>'
def asset(label='商品图1',kind='product',meta='外观参考',warn=False,stack=False):
    return f'<div class="asset {"video" if kind=="video" else ""} {"warn" if warn else ""} {"stack" if stack else ""}"><div class="art">{art(kind)}{"<span class=play>▶</span>" if kind=="video" else ""}</div><div class="asset-info"><strong>{label}</strong><span>{meta}</span><div class="ops">预览 · 替换 · 删除</div></div><span class="x">×</span></div>'
def notice(text,kind='',actions=''):
    return f'<div class="notice {kind}"><span class="n-icon">{"!" if kind else "✓"}</span><div>{text}</div>{f"<div class=actions>{actions}</div>" if actions else ""}</div>'
def prompt(text=None):
    return '<div class="prompt"><div class="label">创意 Tips <span class="muted">ⓘ</span></div>'+(text or '使用 <span class="token">@商品图1</span> 作为产品外观参考，使用 <span class="token">@数字人1</span> 作为人物参考。<br>参考 <span class="token">@视频1</span> 的动作与运镜，生成一段自然的日常使用视频。')+'</div>'
def file_row(name,sub,status='上传失败',percent=None):
    return f'<div class="file-row"><div class="file-ico">{icon("video",19)}</div><div class="file-details"><div class="file-name">{name}</div><div class="file-sub {"red" if status=="上传失败" else ""}">{sub}</div>{f"<div class=progress><i style=width:{percent}%></i></div>" if percent else ""}</div><span class="state-pill {"error" if status=="上传失败" else ""}">{status}</span><span class="muted" style="font-size:11px">{"替换 · 移除" if status=="上传失败" else "取消"}</span></div>'

def panel(kind):
    mini=kind=='mini'; wan=kind=='wan_duration'; restore=kind=='restore'
    heading='生成设置'
    resolutions='<button class="option on">720P</button><button class="option" '+('disabled' if mini else '')+'>1080P'+('<small>此模型不支持</small>' if mini else '')+'</button>'
    ratios=''.join(f'<button class="option {"on" if x=="9:16" else ""}"><i class="ratio-box {"vertical" if x in ["9:16","3:4"] else ""}"></i>{x}</button>' for x in ['16:9','9:16','1:1','4:3','3:4'])
    hint='<div class="panel-hint">Seedance 2.0 Mini 最高支持 720P。<br>此限制与是否上传参考视频无关。</div>' if mini else ''
    dur='20' if wan else '18' if restore else '15'
    maximum='30' if restore or wan else '15'
    rangeHtml=f'<div class="range {"limit" if wan else ""}"><i></i></div><div class="range-label"><span>{"2" if wan or restore else "4"} 秒</span>{"<span style=color:#b27854>18 秒上限</span>" if wan else ""}<span>{maximum} 秒</span></div>'
    durationHelp='<div class="panel-hint">输入视频 12 秒＋输出 20 秒＝32 秒<br>合计不得超过 30 秒，输出最长可选 18 秒。</div><button class="apply">改为 18 秒</button>' if wan else '<div class="panel-hint" style="color:#5f856f;background:#eff7f1">已无视频输入，上限恢复为 30 秒。<br>当前选择仍为 18 秒。</div>' if restore else ''
    return f'<div class="panel"><h3>{heading}<span style="float:right;color:#a9b0ac">×</span></h3><div class="panel-label">分辨率</div><div class="optionrow">{resolutions}</div>{hint}<div class="panel-label">宽高比</div><div class="optionrow">{ratios}</div><div class="duration-value"><span>生成时长</span><b class="{"red" if wan else ""}">{dur} <small>秒</small></b></div>{rangeHtml}{durationHelp}<div class="panel-label">音频</div><div class="optionrow"><button class="option on">带音频</button><button class="option">无声音</button></div></div>'

def render(s):
    mode=s['mode']; model=s['model']; vids=1; imgs=2; total=6; outdur='15s'; blocked=False; gen='生成视频'; pop=''; body=''; hook='Hook 模板'; ratio='9:16'; helpLine=''; limits=10 if model=='Seedance 2.5' else 5 if model=='Wan 3.0' else 3; ilim=30 if model=='Seedance 2.5' else 10 if model=='Wan 3.0' else 9; tlim=30 if model=='Seedance 2.5' else 15
    standard_assets=asset()+asset('数字人1','person','可用虚拟人像')+asset('视频1','video','6.0 秒 · 720p')+add('参考视频','video',new=True)+add('商品图','box')+add('数字人','person')
    if mode=='empty':
        imgs=vids=total=0; blocked=True; body='<div class="emptyrow">'+add('商品图','box')+add('数字人','person')+add('参考视频','video',new=True)+'<div class="placeholder-copy"><strong>创意 Tips ⓘ</strong>描述你想生成的视频，也可以引用商品图、数字人和参考视频。<br>例如：使用 @商品图1 作为产品外观参考，参考 @视频1 的运镜与动作，<br>生成一段真实自然的日常使用视频。</div></div><div class="mini-tip"><strong>上传参考视频</strong><br>'+s['tips']+'<br>支持 24–60 fps，可与商品图、数字人一起使用。</div><div style="height:107px"></div>'
    elif mode=='upload':
        imgs=0;vids=2;total=0;blocked=True;gen='等待素材就绪';body='<div class="uploadbox">'+file_row('日常使用.mp4','18.6 MB · 6.0 秒 · 720p','校验中')+file_row('产品展示.mov','已上传 26.4 / 42.0 MB','上传中 63%',63)+'</div>'+notice('视频就绪后会显示可引用编号。上传和校验完成前，请稍候。')+prompt('参考视频的运镜，生成一段自然的产品使用视频。')
    elif mode=='invalid':
        imgs=vids=total=0;blocked=True;gen='请添加可用素材';body='<div class="uploadbox">'+file_row('厨房日常.mp4','大小 118 MB，当前模型单个视频不得超过 100 MB')+file_row('开箱展示.mov','时长 18.0 秒，当前模型要求单个视频为 1–15 秒')+file_row('产品特写.mp4','帧率 12 fps，当前模型要求至少 16 fps')+'</div>'+notice('3 个文件均未加入参考素材，请替换为符合要求的视频。','error')
    elif mode=='video_cap':
        imgs=0;vids=3;total=12;body='<div class="assetrow">'+''.join(asset(f'视频{i}','video','4.0 秒 · 720p') for i in range(1,4))+add('参考视频','video',True,'已达 3 段')+add('商品图','box')+add('数字人','person')+'</div>'+notice('<strong>参考视频已达 3 段上限。</strong> 如需更换，请删除或替换已有视频；仍可添加商品图和数字人。','warning')+prompt('参考 <span class="token">@视频1</span> 的运镜和 <span class="token">@视频2</span> 的动作，生成一段新视频。')
    elif mode=='duration_cap':
        imgs=0;vids=2;total=14;body='<div class="assetrow">'+asset('视频1','video','8.0 秒 · 720p')+asset('视频2','video','6.0 秒 · 720p')+add('参考视频','video',True,'剩余 1 秒')+add('商品图','box')+add('数字人','person')+'</div><div class="err-block"><strong>新增的「产品特写.mp4」未加入：累计时长将超过 15 秒。</strong><div class="smallmetric"><span class="metric"><b>14 秒</b>已有参考视频</span><span>＋</span><span class="metric"><b>3 秒</b>本次新增</span><span>＝</span><span class="metric"><b>17 秒</b>超过上限 2 秒</span></div></div><div class="bottomhint">仅使用已通过校验的 2 段视频。可先替换旧视频，再重新添加。</div>'+prompt('参考 <span class="token">@视频1</span> 的镜头节奏，生成产品使用视频。')
    elif mode=='image_cap':
        imgs=9;vids=1;total=4;body='<div class="assetrow">'+asset('商品图 1–8','product','共 8 张 · 外观参考',stack=True)+asset('数字人1','person','1 张可用人像')+asset('视频1','video','4.0 秒 · 720p')+add('商品图','box',True,'已达 9 张')+add('数字人','person',True,'图片额度已满')+add('参考视频','video',new=True)+'</div>'+notice('<strong>图片已使用 9 / 9 张。</strong> 包含 8 张商品图和 1 张数字人人像；仍可添加参考视频。','warning')+prompt()
    elif mode=='wan_duration':
        vids=1;imgs=1;total=12;outdur='20s';blocked=True;gen='请调整生成时长';body='<div class="assetrow">'+asset()+asset('视频1','video','12.0 秒 · 720p')+add('参考视频','video',new=True)+'</div>'+prompt('使用 <span class="token">@商品图1</span> 作为外观参考，<br>参考 <span class="token">@视频1</span> 的运镜，生成新的使用视频。')+notice('当前生成时长超出上限，请在设置中调整至 18 秒以内。','error');pop=panel(mode)
    elif mode=='switch':
        imgs=1;vids=4;total=20;outdur='30s';body='<div class="assetrow">'+asset()+''.join(asset(f'视频{i}','video','5.0 秒 · 720p') for i in range(1,5))+'</div>'+prompt('参考多段视频的镜头语言，生成 30 秒的产品日常故事。');pop='<div class="shade"></div><div class="dialog"><h3>切换到 Seedance 2.0？</h3><p>当前有 3 项设置与新模型不兼容。切换不会自动删除素材或修改参数。</p><table><tr><th>需要调整的项目</th><th>当前配置</th><th>新模型限制</th></tr><tr><td>参考视频数量</td><td>4 段</td><td>最多 3 段</td></tr><tr><td>视频累计时长</td><td>20 秒</td><td>不超过 15 秒</td></tr><tr><td>生成时长</td><td>30 秒</td><td>最长 15 秒</td></tr></table><div class="callout">切换后，请手动调整标红的素材和参数。<br>全部符合要求后才可生成。</div><div class="dialog-actions"><button class="secondary">保留原模型</button><button class="primary">切换并手动调整</button></div></div>'
    elif mode=='roles':
        imgs=2;vids=0;total=0;ratio='跟随首帧';body='<div class="assetrow">'+asset('首帧图片','product','首帧约束')+asset('尾帧图片','product','尾帧约束')+add('参考视频','video',new=True)+'</div>'+prompt('保持首帧和尾帧图片的画面关系，生成产品展示视频。');pop='<div class="shade"></div><div class="dialog"><h3>使用视频参考需要取消首尾帧约束</h3><p>首帧／尾帧与参考视频不能同时使用。可以保留图片，改为普通参考素材。</p><div class="row-role"><span><b>首帧图片</b><br>严格首帧</span><span>→</span><span><b>参考图1</b><br>外观／构图参考</span></div><div class="row-role"><span><b>尾帧图片</b><br>严格尾帧</span><span>→</span><span><b>参考图2</b><br>外观／构图参考</span></div><div class="callout">转换后，不再保证生成视频的首尾帧与图片严格一致。图片不会被删除。</div><div class="dialog-actions"><button class="secondary">保留首尾帧</button><button class="primary">改为参考并继续</button></div></div>'
    elif mode=='hook':
        hook='反差开场';body='<div class="assetrow">'+standard_assets+'</div>'+prompt('前 3 秒采用反差开场 Hook；3 秒后参考 <span class="token">@视频1</span> 的运镜和动作。<br>商品外观使用 <span class="token">@商品图1</span>，人物使用 <span class="token">@数字人1</span>。')+notice('<strong>可以同时使用 Hook 和视频参考。</strong><br>建议在描述中说明各自作用的时间段，避免开场要求相互矛盾。','warning','<button class="linkbutton">修改描述</button><button class="linkbutton">取消 Hook</button>')
    elif mode=='dangling':
        vids=0;total=0;blocked=True;gen='请处理失效引用';body='<div class="assetrow">'+asset()+asset('数字人1','person','可用虚拟人像')+add('参考视频','video',new=True)+'</div>'+prompt('使用 <span class="token">@商品图1</span> 作为外观参考，<span class="token">@数字人1</span> 作为人物参考。<br>参考 <span class="token bad">@视频1 · 已删除</span> 的动作与运镜，生成一段日常使用视频。')+notice('<strong>视频1 已删除，描述中仍有 1 处引用。</strong><br>请删除该引用，或重新选择参考视频。','error','<button class="linkbutton">删除引用</button><button class="linkbutton">重新选择</button>')
    elif mode=='restore':
        vids=0;imgs=1;total=0;outdur='18s';body='<div class="assetrow">'+asset()+add('参考视频','video',new=True)+add('商品图','box')+add('数字人','person')+'</div>'+prompt('使用 <span class="token">@商品图1</span> 作为外观参考，<br>生成自然的日常使用视频。')+notice('参考视频及其引用已移除。<br>生成时长可选上限已恢复，当前 18 秒保持不变。');pop=panel(mode)
    elif mode=='face':
        imgs=1;vids=1;total=6;blocked=True;gen='请替换不可用素材';body='<div class="assetrow">'+asset()+asset('视频1','person','平台校验未通过',warn=True)+add('参考视频','video',new=True)+add('数字人','person')+'</div>'+notice('<strong>这段视频暂不可用于当前 Seedance 模型。</strong><br>平台校验结果：真人素材未满足当前输入条件。请替换为平台支持的授权或信任素材。','error','<button class="linkbutton">替换视频</button><button class="linkbutton">选择可用数字人</button>')+prompt('使用商品图作为外观参考，生成一段日常使用视频。')
    elif mode=='task_error':
        imgs=1;total=6;body='<div class="assetrow">'+asset()+asset('视频1','video','6.0 秒 · 720p')+'</div>'+prompt('把 <span class="token">@视频1</span> 中的商品替换成 <span class="token">@商品图1</span>。')+'<div class="taskbox"><h4>参考生成未完成 · 任务类型不匹配</h4><p>当前描述被识别为对原视频进行编辑，与“参考生成”不一致。<br>可以修改为：参考视频1的运镜，使用商品图1生成一段新视频。</p><button class="linkbutton">返回修改描述</button><span class="muted" style="font-size:10px;margin-left:16px">素材与设置已保留</span></div>';gen='修改后重新生成';blocked=True
    else:
        body='<div class="assetrow">'+standard_assets+'</div>'+prompt()
        if mode=='mini':pop=panel(mode)
        else:body+=notice('素材已就绪，可继续设置生成参数。商品图、数字人和参考视频可以同时使用。')
    counts=f'图片 <b>{imgs}/{ilim}</b>　视频 <b>{vids}/{limits}</b><br>视频合计 {total}/{tlim} 秒'
    if mode=='upload':counts='视频 0 段可用<br>2 个文件处理中'
    if mode=='face':counts='图片 1 张可用<br>视频 1 段待替换'
    toolbar=f'<div class="toolbar"><button class="ctrl {"selected" if mode=="switch" else ""}">{icon("model")}{model}<span class="chevron">⌄</span></button><button class="ctrl">♧ {hook}<span class="chevron">⌄</span></button><button class="ctrl {"selected" if mode=="mini" else ""}">{icon("settings")}720P</button><button class="ctrl {"warn" if mode=="wan_duration" else ""}">{icon("clock")}{outdur}</button><button class="ctrl">▯ {ratio}</button><button class="ctrl">{icon("sound")}<span class="chevron">⌄</span></button><div class="counts">{counts}</div><button class="gen" {"disabled" if blocked else ""}>{icon("spark",15)}{gen}</button></div>'
    recent='<div class="recent"><div class="recent-head"><span>最近任务　<span class="captionpill">创意生成</span></span><span>查看全部 ›</span></div><div class="recent-list">'+''.join(f'<div class="recent-card"><div class="recent-thumb">{icon("video",24)}</div><div>商品视频生成<small>09/17 10:{12+i*7}　·　示例任务</small></div></div>' for i in range(3))+'</div></div>'
    notes=''.join(f'<div class="note"><em>0{i+1}</em><span>{n}</span></div>' for i,n in enumerate(s['notes']))
    return f'<div class="frame {mode}"><div class="frame-top"><div class="titlebox"><div class="pnum">{s["id"]}</div><div><h2>{s["title"]}</h2><p>{s["subtitle"]}</p></div></div><span class="tag {"amber" if s["tag"] not in ["正常流程","恢复状态","过程状态"] else ""}">{s["tag"]}</span></div><div class="app"><div class="hero"><h1>创意助手</h1><p>选择预设，添加产品和数字人，几分钟内生成可投放的视频广告</p></div><div class="workspace"><div class="tabs"><span class="selected">创意生成</span><span>创意报告</span><span>创意分析</span><span>创意脚本</span><div class="mode-label">参考生成</div></div><div class="body">{body}</div>{toolbar}</div>{recent}{pop}</div><div class="summary"><div class="summary-label"><span>交互说明 / {s["rule"]}</span><span>CREATISIGNAL · 静态原型示例 · {s["id"]} / 16</span></div><div class="notes">{notes}</div></div></div>'

