def inline(t):
    import re
    t=html.escape(t)
    t=re.sub(r'`([^`]+)`',r'<code>\1</code>',t)
    t=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',t)
    t=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',r'<a href="\2">\1</a>',t)
    return t

md=(ROOT/'需求方案.md').read_text(encoding='utf-8')
rows=md.splitlines(); output=[];i=0
while i<len(rows):
    line=rows[i]
    if not line.strip():i+=1;continue
    if line.startswith('|'):
        block=[]
        while i<len(rows) and rows[i].startswith('|'):block.append(rows[i]);i+=1
        cells=lambda r:[x.strip() for x in r.strip('|').split('|')]
        output.append('<table><thead><tr>'+''.join('<th>'+inline(x)+'</th>' for x in cells(block[0]))+'</tr></thead><tbody>')
        for row in block[2:]:output.append('<tr>'+''.join('<td>'+inline(x)+'</td>' for x in cells(row))+'</tr>')
        output.append('</tbody></table>');continue
    if line.startswith('#'):
        n=len(line)-len(line.lstrip('#'));output.append(f'<h{n}>'+inline(line[n:].strip())+f'</h{n}>')
    elif line.startswith('- '):output.append('<p>• '+inline(line[2:])+'</p>')
    else:output.append('<p>'+inline(line)+'</p>')
    i+=1
figures=''.join(f'<figure><a href="prototype/index.html?scene={s["id"]}"><img loading="lazy" src="prototype/png/{s["id"]}.png" alt="{s["id"]} {s["title"]}"></a><figcaption>{s["id"]} {s["title"]} · {s["rule"]}</figcaption></figure>' for s in scenes)
